  const [connectionError,setConnectionError]=useState(''); const refreshId=useRef(0); const sideRef=useRef(null);
  useEffect(()=>{sideRef.current?.scrollTo({top:0,behavior:'instant'});if((room||request)&&window.matchMedia('(max-width:760px)').matches)sideRef.current?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})},[room,request]);
  async function load(quiet=false){const current=++refreshId.current;try{const d=await api(`/api/world${date?`?date=${date}`:''}`);if(current===refreshId.current){setData(d);setConnectionError('');if(!quiet)setError('')}}catch(e){if(current===refreshId.current)setConnectionError(e.message)}}
  useEffect(()=>{load();const id=setInterval(()=>load(true),5000);return()=>clearInterval(id)},[date]);
  useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),4000);return()=>clearTimeout(id)},[toast]);
  async function act(url,body={},headers={}){setBusy(true);setError('');try{const result=await api(url,body,headers);await load(true);setToast('Saved and checked in StayWeave.');return result}catch(e){setError(e.message);return null}finally{setBusy(false)}}
  async function openGuest(id){const result=await act(`/api/world/requests/${id}/guest-link`);if(result)location.href=new URLSearchParams(location.search).get('demo')==='1'?result.path.replace('/?','/?demo=1&'):result.path}
  if(!data)return <div className="sw sw-loading"><span className="sw-logo">w</span><h2>Opening Harbor House…</h2><ErrorNote error={error||connectionError}/>{(error||connectionError)&&<Action onClick={()=>load()}>Retry</Action>}</div>;
