    <aside className="sw-rail"><a href="/" className="sw-logo" aria-label="StayWeave home">w</a><div>{[[Compass,'property','Your property'],[MessageCircle,'inbox','All requests'],[ClipboardCheck,'work','Operations']].map(([Icon,id,title])=><button className={view===id?'active':''} aria-label={title} title={title} key={id} onClick={()=>{setView(id);setDesk(id==='inbox'?'guests':'tasks');resetSide()}}><Icon size={21}/>{id==='inbox'&&s.attention>0&&<i/>}</button>)}</div><button aria-label="Connections and scope" title="Connections and scope" onClick={()=>openChannels()}><Settings2 size={20}/></button><span className="sw-owner-avatar">Y</span></aside>
